4002.sent:
// Storage-key retrieval that is part of an ARM/Bicep deployment (shared CorrelationId)
// = the Snyk listKeys->deployment-output leak vector. Differs from the
// Anomalous_Listing_Of_Storage_Keys (same-user/different-IP) hunting rule.
let lookback = 7d;
let deployments = AzureActivity
| where TimeGenerated > ago(lookback)
| where OperationNameValue =~ "Microsoft.Resources/deployments/write"
| where ActivityStatusValue in ("Succeeded","Success","Accepted","Started")
| distinct CorrelationId, DeployCaller = Caller, DeployIp = CallerIpAddress;
AzureActivity
| where TimeGenerated > ago(lookback)
| where OperationNameValue =~ "Microsoft.Storage/storageAccounts/listKeys/action"
| where ActivityStatusValue in ("Succeeded","Success")
| join kind=inner deployments on CorrelationId
| project TimeGenerated, Caller, CallerIpAddress, DeployCaller, DeployIp, ResourceGroup, SubscriptionId, ResourceId, CorrelationId
| order by TimeGenerated desc

